+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+/**
+ * Local state string type for voice broadcast recording.
+ * Kept here to avoid circular imports with the voice-broadcast index.
+ */
+export type VoiceBroadcastState = "started" | "paused" | "running" | "stopped";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "io.element.voice_broadcast.recording_state_changed",
+}
+
+type VoiceBroadcastRecordingEventHandlerMap = {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (state: VoiceBroadcastState) => void;
+};
+
+/**
+ * Model representing a single Voice Broadcast recording state.
+ * Emits events when the recording state changes.
+ */
+export class VoiceBroadcastRecording
+    extends TypedEventEmitter<VoiceBroadcastRecordingEvent, VoiceBroadcastRecordingEventHandlerMap> {
+    public readonly roomId: string;
+    public readonly senderId: string;
+
+    private _state: VoiceBroadcastState;
+
+    public constructor(roomId: string, senderId: string, initialState: VoiceBroadcastState = "started") {
+        super();
+        this.roomId = roomId;
+        this.senderId = senderId;
+        this._state = initialState;
+    }
+
+    public get state(): VoiceBroadcastState {
+        return this._state;
+    }
+
+    public setState(state: VoiceBroadcastState): void {
+        if (this._state === state) return;
+        this._state = state;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged, this._state);
+    }
+
+    public pause(): void {
+        this.setState("paused");
+    }
+
+    public resume(): void {
+        this.setState("running");
+    }
+
+    public stop(): void {
+        this.setState("stopped");
+    }
+
+    public destroy(): void {
+        this.removeAllListeners(VoiceBroadcastRecordingEvent.StateChanged);
+    }
+}
