+
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+import { VoiceBroadcastRecording } from "../models/VoiceBroadcastRecording";
+
+export enum VoiceBroadcastRecordingsStoreEvent {
+    RecordingAdded = "io.element.voice_broadcast.recording_added",
+    RecordingRemoved = "io.element.voice_broadcast.recording_removed",
+}
+
+type VoiceBroadcastRecordingsStoreEventHandlerMap = {
+    [VoiceBroadcastRecordingsStoreEvent.RecordingAdded]: (recording: VoiceBroadcastRecording) => void;
+    [VoiceBroadcastRecordingsStoreEvent.RecordingRemoved]: (recording: VoiceBroadcastRecording) => void;
+};
+
+/**
+ * Store to manage multiple voice broadcast recordings.
+ */
+export class VoiceBroadcastRecordingsStore
+    extends TypedEventEmitter<VoiceBroadcastRecordingsStoreEvent, VoiceBroadcastRecordingsStoreEventHandlerMap> {
+    private static internalInstance: VoiceBroadcastRecordingsStore | undefined;
+
+    public static get instance(): VoiceBroadcastRecordingsStore {
+        if (!this.internalInstance) {
+            this.internalInstance = new VoiceBroadcastRecordingsStore();
+        }
+        return this.internalInstance;
+    }
+
+    private recordingsByKey: Map<string, VoiceBroadcastRecording> = new Map();
+
+    /**
+     * Computes a key to identify a recording for a given room and sender.
+     */
+    public static getKey(roomId: string, senderId: string): string {
+        return `${roomId}|${senderId}`;
+    }
+
+    public add(recording: VoiceBroadcastRecording): void {
+        const key = VoiceBroadcastRecordingsStore.getKey(recording.roomId, recording.senderId);
+        if (this.recordingsByKey.has(key)) return;
+        this.recordingsByKey.set(key, recording);
+        this.emit(VoiceBroadcastRecordingsStoreEvent.RecordingAdded, recording);
+    }
+
+    public remove(recording: VoiceBroadcastRecording): void {
+        const key = VoiceBroadcastRecordingsStore.getKey(recording.roomId, recording.senderId);
+        if (!this.recordingsByKey.has(key)) return;
+        this.recordingsByKey.delete(key);
+        this.emit(VoiceBroadcastRecordingsStoreEvent.RecordingRemoved, recording);
+    }
+
+    public get(roomId: string, senderId: string): VoiceBroadcastRecording | undefined {
+        return this.recordingsByKey.get(VoiceBroadcastRecordingsStore.getKey(roomId, senderId));
+    }
+
+    public getAll(): VoiceBroadcastRecording[] {
+        return Array.from(this.recordingsByKey.values());
+    }
+}
