+import { MatrixClient } from "matrix-js-sdk/src/matrix";
+
+import { VoiceBroadcastRecording } from "../models/VoiceBroadcastRecording";
+import { VoiceBroadcastRecordingsStore } from "../stores/VoiceBroadcastRecordingsStore";
+
+/**
+ * Utility to create and register a new voice broadcast recording.
+ */
+export const startNewVoiceBroadcastRecording = (
+    client: MatrixClient,
+    roomId: string,
+): VoiceBroadcastRecording => {
+    if (!client) throw new Error("MatrixClient is required");
+    if (!roomId) throw new Error("roomId is required");
+
+    const recording = new VoiceBroadcastRecording(roomId, client.getUserId());
+    VoiceBroadcastRecordingsStore.instance.add(recording);
+    return recording;
+};
